# Physiotherapy Notes App

A simple Flask app with SQLite storage, user login, and append-only note versioning.

## Project structure

```
physio_app/
├── app.py
├── requirements.txt
└── templates/
    ├── base.html
    ├── login.html
    ├── patients.html
    ├── patient.html
    └── note_form.html
```

## `requirements.txt`

```
flask
werkzeug
```

## `app.py`

```python
import os
import sqlite3
from datetime import datetime
from functools import wraps

from flask import (
    Flask, g, render_template, request, redirect,
    url_for, session, flash, abort,
)
from werkzeug.security import generate_password_hash, check_password_hash

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
DB_PATH = os.path.join(BASE_DIR, "physio.db")

app = Flask(__name__)
app.secret_key = os.environ.get("SECRET_KEY", "dev-secret-change-me")

# ---------- Database helpers ----------

def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.executescript(
        """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            password_hash TEXT NOT NULL
        );

        CREATE TABLE IF NOT EXISTS patients (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            full_name TEXT NOT NULL,
            created_at TEXT NOT NULL
        );

        -- Append-only: every edit inserts a NEW row.
        -- The current note = latest version per visit_id.
        CREATE TABLE IF NOT EXISTS notes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            visit_id INTEGER NOT NULL,
            patient_id INTEGER NOT NULL REFERENCES patients(id),
            version INTEGER NOT NULL,
            body TEXT NOT NULL,
            created_at TEXT NOT NULL,
            created_by TEXT NOT NULL
        );

        CREATE INDEX IF NOT EXISTS idx_notes_visit
            ON notes(visit_id, version);
        CREATE INDEX IF NOT EXISTS idx_notes_patient
            ON notes(patient_id);
        """
    )

    # Seed a default user if none exists
    cur = db.execute("SELECT COUNT(*) AS c FROM users")
    if cur.fetchone()["c"] == 0:
        db.execute(
            "INSERT INTO users (username, password_hash) VALUES (?, ?)",
            ("physio", generate_password_hash("changeme")),
        )
    db.commit()
    db.close()

# ---------- Auth ----------

def login_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        if not session.get("user_id"):
            return redirect(url_for("login", next=request.path))
        return f(*args, **kwargs)
    return wrapper

@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        username = request.form.get("username", "").strip()
        password = request.form.get("password", "")
        row = get_db().execute(
            "SELECT * FROM users WHERE username = ?", (username,)
        ).fetchone()
        if row and check_password_hash(row["password_hash"], password):
            session.clear()
            session["user_id"] = row["id"]
            session["username"] = row["username"]
            return redirect(request.args.get("next") or url_for("patients"))
        flash("Invalid username or password", "error")
    return render_template("login.html")

@app.route("/logout")
def logout():
    session.clear()
    return redirect(url_for("login"))

# ---------- Patients ----------

@app.route("/")
@login_required
def patients():
    rows = get_db().execute(
        "SELECT * FROM patients ORDER BY full_name"
    ).fetchall()
    return render_template("patients.html", patients=rows)

@app.route("/patients/new", methods=["POST"])
@login_required
def new_patient():
    name = request.form.get("full_name", "").strip()
    if not name:
        flash("Name is required", "error")
    else:
        db = get_db()
        db.execute(
            "INSERT INTO patients (full_name, created_at) VALUES (?, ?)",
            (name, datetime.now().isoformat(timespec="seconds")),
        )
        db.commit()
    return redirect(url_for("patients"))

# ---------- Patient detail (visits + notes) ----------

@app.route("/patients/<int:patient_id>")
@login_required
def patient_detail(patient_id):
    db = get_db()
    patient = db.execute(
        "SELECT * FROM patients WHERE id = ?", (patient_id,)
    ).fetchone()
    if not patient:
        abort(404)

    # Latest version of each visit
    visits = db.execute(
        """
        SELECT visit_id,
               MAX(version) AS latest_version,
               MAX(created_at) AS last_updated
        FROM notes
        WHERE patient_id = ?
        GROUP BY visit_id
        ORDER BY visit_id DESC
        """,
        (patient_id,),
    ).fetchall()

    # Attach current body text to each visit
    visit_list = []
    for v in visits:
        current = db.execute(
            "SELECT * FROM notes WHERE visit_id = ? AND version = ?",
            (v["visit_id"], v["latest_version"]),
        ).fetchone()
        visit_list.append(current)

    return render_template(
        "patient.html", patient=patient, visits=visit_list
    )

# ---------- New visit / note ----------

@app.route("/patients/<int:patient_id>/visits/new", methods=["GET", "POST"])
@login_required
def new_visit(patient_id):
    db = get_db()
    patient = db.execute(
        "SELECT * FROM patients WHERE id = ?", (patient_id,)
    ).fetchone()
    if not patient:
        abort(404)

    if request.method == "POST":
        body = request.form.get("body", "").strip()
        if not body:
            flash("Note cannot be empty", "error")
        else:
            # New visit_id = max existing + 1 (scoped to patient)
            row = db.execute(
                "SELECT COALESCE(MAX(visit_id), 0) AS m FROM notes WHERE patient_id = ?",
                (patient_id,),
            ).fetchone()
            new_visit_id = row["m"] + 1
            db.execute(
                """INSERT INTO notes
                   (visit_id, patient_id, version, body, created_at, created_by)
                   VALUES (?, ?, 1, ?, ?, ?)""",
                (
                    new_visit_id,
                    patient_id,
                    body,
                    datetime.now().isoformat(timespec="seconds"),
                    session["username"],
                ),
            )
            db.commit()
            return redirect(url_for("patient_detail", patient_id=patient_id))

    return render_template("note_form.html", mode="new", patient=patient, note=None)

# ---------- Edit visit / note (append new version) ----------

@app.route(
    "/patients/<int:patient_id>/visits/<int:visit_id>/edit",
    methods=["GET", "POST"],
)
@login_required
def edit_visit(patient_id, visit_id):
    db = get_db()
    patient = db.execute(
        "SELECT * FROM patients WHERE id = ?", (patient_id,)
    ).fetchone()
    if not patient:
        abort(404)

    current = db.execute(
        """SELECT * FROM notes WHERE patient_id = ? AND visit_id = ?
           ORDER BY version DESC LIMIT 1""",
        (patient_id, visit_id),
    ).fetchone()
    if not current:
        abort(404)

    if request.method == "POST":
        body = request.form.get("body", "").strip()
        if not body:
            flash("Note cannot be empty", "error")
        else:
            next_version = current["version"] + 1
            db.execute(
                """INSERT INTO notes
                   (visit_id, patient_id, version, body, created_at, created_by)
                   VALUES (?, ?, ?, ?, ?, ?)""",
                (
                    visit_id,
                    patient_id,
                    next_version,
                    body,
                    datetime.now().isoformat(timespec="seconds"),
                    session["username"],
                ),
            )
            db.commit()
            return redirect(url_for("patient_detail", patient_id=patient_id))

    return render_template(
        "note_form.html", mode="edit", patient=patient, note=current
    )

# ---------- History ----------

@app.route(
    "/patients/<int:patient_id>/visits/<int:visit_id>/history"
)
@login_required
def visit_history(patient_id, visit_id):
    db = get_db()
    patient = db.execute(
        "SELECT * FROM patients WHERE id = ?", (patient_id,)
    ).fetchone()
    if not patient:
        abort(404)

    versions = db.execute(
        """SELECT * FROM notes WHERE patient_id = ? AND visit_id = ?
           ORDER BY version DESC""",
        (patient_id, visit_id),
    ).fetchall()
    return render_template(
        "note_history.html",
        patient=patient,
        versions=versions,
        visit_id=visit_id,
    )

# ---------- Admin: change password (basic) ----------

@app.route("/change-password", methods=["GET", "POST"])
@login_required
def change_password():
    if request.method == "POST":
        current_pw = request.form.get("current", "")
        new_pw = request.form.get("new", "")
        db = get_db()
        row = db.execute(
            "SELECT * FROM users WHERE id = ?", (session["user_id"],)
        ).fetchone()
        if not check_password_hash(row["password_hash"], current_pw):
            flash("Current password is wrong", "error")
        elif len(new_pw) < 8:
            flash("New password must be at least 8 characters", "error")
        else:
            db.execute(
                "UPDATE users SET password_hash = ? WHERE id = ?",
                (generate_password_hash(new_pw), session["user_id"]),
            )
            db.commit()
            flash("Password updated", "ok")
            return redirect(url_for("patients"))
    return render_template("change_password.html")

if __name__ == "__main__":
    init_db()
    app.run(debug=True, host="127.0.0.1", port=5000)
